SELECT T.EMPID, T.LOCAL_NAME AS NAME, GET_DEPT_NAME(T.DEPTNO, #{lang, jdbcType=VARCHAR}) AS DEPT_NAME FROM HR_EMPLOYEE T WHERE T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND T.ACTIVITY = '1' AND T.EMPID IN
