SELECT T.EMPID, T.TEACHER_NAME AS NAME, (SELECT GET_DEPT_NAME(H.DEPTNO, #{lang, jdbcType=VARCHAR}) FROM HR_EMPLOYEE H WHERE H.PERSON_ID = T.PERSON_ID AND ROWNUM = 1) AS DEPT_NAME FROM EDU_TEACHER_MANAGER T WHERE T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND T.ACTIVITY = '1' AND T.EMPID IN
#{e, jdbcType=VARCHAR}
ORDER BY T.EMPID
